// Data generator provider
public class MyDataProvider extends ForgeDataProvider {
    private final DataGenerator gen;
    private final ExistingFileHelper existingFileHelper;

    public MyDataProvider(DataGenerator gen, ExistingFileHelper efh) {
        this.gen = gen;
        this.existingFileHelper = efh;
    }

    @Override
    public void run(HashCache cache) {
        // Add block tags
        BlockTagsProvider blockTags = new BlockTagsProvider(gen, MODID, cache, existingFileHelper) {
            @Override
            protected void addTags() {
                tag(BlockTags.MINEABLE_WITH_PICKAXE)
                    .add(MyBlocks.MY_BLOCK.get());
                tag(new ResourceLocation(MODID, "my_custom_tag"))
                    .add(Blocks.STONE);
            }
        };
        gen.addProvider(true, blockTags);

        // Add recipes
        gen.addProvider(true, new RecipeProvider(gen) {
            @Override
            protected void buildRecipes() {
                ShapedRecipeBuilder.shaped(Items.DIAMOND)
                    .pattern("AAA")
                    .pattern("ABA")
                    .pattern("AAA")
                    .define('A', Items.COAL)
                    .define('B', Items.EMERALD)
                    .save(gen);
            }
        });
    }

    @Override
    public String getName() { return MODID + " data provider"; }
}
